package termgen

import (
	"bytes"
	"fmt"
	"go/format"
	"strconv"
)

// SourceInfo is the provenance the generated file records: the TERM release
// ref from the pin's MANIFEST.txt, and the repo-relative path and the sha256
// [Run] computed over the bytes of each pinned file (openehr_terminology.xml
// in Path and SHA256, openehr_external_terminologies.xml in ExternalPath and
// ExternalSHA256).
type SourceInfo struct {
	Ref            string
	Path           string
	SHA256         string
	ExternalPath   string
	ExternalSHA256 string
}

// Render emits openehr_gen.go from the pin as [Merge] joined it: the
// generated-file header and its provenance, the Version, SourceSHA256 and
// ExternalSourceSHA256 constants, one exported variable per group and per
// code set in source order, and the unexported groups / codeSets registry
// slices the package's accessors range over.
//
// The output is run through go/format, so it is gofmt-clean, and it depends
// on nothing but t and src, so it is byte-deterministic. Together these let
// `make termgen-verify` treat any difference from the committed file as
// drift.
func Render(t *Terminology, src SourceInfo) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString("// Code generated by termgen; DO NOT EDIT.\n")
	fmt.Fprintf(&b, "// Source: openEHR TERM %s (terminology version %s):\n", src.Ref, t.Version)
	fmt.Fprintf(&b, "// %s (sha256 %s) and\n", src.Path, src.SHA256)
	fmt.Fprintf(&b, "// %s (sha256 %s).\n", src.ExternalPath, src.ExternalSHA256)
	b.WriteString("// Regenerate: make termgen. Verify: make termgen-verify.\n\n")
	b.WriteString("package terminology\n\n")

	b.WriteString("// Version is the openEHR Terminology release the tables below are generated from.\n")
	fmt.Fprintf(&b, "const Version = %s\n\n", strconv.Quote(t.Version))
	b.WriteString("// SourceSHA256 is the sha256 of the pinned openehr_terminology.xml the tables were generated from.\n")
	fmt.Fprintf(&b, "const SourceSHA256 = %s\n\n", strconv.Quote(src.SHA256))
	b.WriteString("// ExternalSourceSHA256 is the sha256 of the pinned openehr_external_terminologies.xml the external code sets were generated from.\n")
	fmt.Fprintf(&b, "const ExternalSourceSHA256 = %s\n\n", strconv.Quote(src.ExternalSHA256))

	for _, g := range t.Groups {
		name := GoName(g.ID)
		fmt.Fprintf(&b, "// %s is the openEHR terminology group %s (openehr_id %s), %s.\n",
			name, strconv.Quote(g.Name), g.ID, plural(len(g.Concepts), "concept"))
		fmt.Fprintf(&b, "var %s = newGroup(%s, %s, []Concept{\n", name, strconv.Quote(g.ID), strconv.Quote(g.Name))
		for _, c := range g.Concepts {
			fmt.Fprintf(&b, "\t{Code: %s, Rubric: %s},\n", strconv.Quote(c.Code), strconv.Quote(c.Rubric))
		}
		b.WriteString("})\n\n")
	}

	for _, cs := range t.CodeSets {
		name := GoName(cs.ID)
		issuer := cs.Issuer
		if cs.IssuedByOpenEHR() {
			issuer = "openEHR"
		}
		fmt.Fprintf(&b, "// %s is the code set %s issued by %s (openehr_id %s, external id %s), %s.\n",
			name, strconv.Quote(cs.Name), issuer, cs.ID, cs.ExternalID, plural(len(cs.Codes), "code"))
		fmt.Fprintf(&b, "var %s = newCodeSet(%s, %s, %s, %s, []string{\n", name,
			strconv.Quote(cs.ID), strconv.Quote(cs.Name), strconv.Quote(cs.Issuer), strconv.Quote(cs.ExternalID))
		for _, c := range cs.Codes {
			fmt.Fprintf(&b, "\t%s,\n", strconv.Quote(c))
		}
		b.WriteString("})\n\n")
	}

	fmt.Fprintf(&b, "// groups is the pin's %s in document order — what Groups and GroupByID range over.\n",
		plural(len(t.Groups), "group"))
	b.WriteString("var groups = []*Group{")
	for i, g := range t.Groups {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(GoName(g.ID))
	}
	b.WriteString("}\n\n")

	fmt.Fprintf(&b, "// codeSets is the pin's %s in source order (openehr_terminology.xml's, then openehr_external_terminologies.xml's) — what CodeSets and CodeSetByID range over.\n",
		plural(len(t.CodeSets), "code set"))
	b.WriteString("var codeSets = []*CodeSet{")
	for i, cs := range t.CodeSets {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(GoName(cs.ID))
	}
	b.WriteString("}\n")

	formatted, err := format.Source(b.Bytes())
	if err != nil {
		return b.Bytes(), fmt.Errorf("gofmt openehr/terminology/openehr_gen.go: %w", err)
	}
	return formatted, nil
}

// plural renders "1 concept" / "9 concepts" for a doc comment.
func plural(n int, noun string) string {
	if n == 1 {
		return "1 " + noun
	}
	return fmt.Sprintf("%d %ss", n, noun)
}
